using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;using MapSharedProps;using MapTunnels.EditorTools;
public static class Cart192Views {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));public static string Out=Path.Combine(Root,"Evidence192");static string Input=>Path.Combine(Root,"Input183");public static string folder;
 static void Check(bool b,string s){if(!b)throw new Exception(s);}static void Shot(Camera c,string n){var t=Shared117Review.Image(c,1280,720);File.WriteAllBytes(Path.Combine(Out,n+".png"),t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}
 static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.08f,.09f,.10f);RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;}
 static Camera Cam(){var c=new GameObject("offscreen").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.035f,.04f,.05f);c.fieldOfView=45;c.nearClipPlane=.03f;return c;}
 static GameObject Prop(string id){return (GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((id.StartsWith("mine_rail_")?"Assets/MapSharedPropsGenerated/Pilot 11":folder)+"/small-"+id+".prefab"));}
 static string Shape(Mesh m)=>JsonUtility.ToJson(new ShapeData{p=m.vertices,n=m.normals,uv=m.uv,c=m.colors,t=m.triangles});[Serializable]class ShapeData{public Vector3[] p,n;public Vector2[] uv;public Color[] c;public int[] t;}
 public static void Studio(){Empty();var plane=GameObject.CreatePrimitive(PrimitiveType.Plane);var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.color=new Color(.25f,.23f,.20f);plane.GetComponent<Renderer>().sharedMaterial=mat;var sun=new GameObject("diagnostic sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.3f;sun.shadows=LightShadows.Soft;var c=Cam();foreach(var shape in new[]{"straight","curve"}){var rail=Prop("mine_rail_"+shape);foreach(var id in new[]{"minecart","minecart_loaded"}){var cart=Prop(id);cart.transform.position=shape=="straight"?new Vector3(0,.14f,-1):new Vector3(2-Mathf.Sqrt(2),.14f,-Mathf.Sqrt(2));cart.transform.rotation=Quaternion.Euler(0,shape=="curve"?-45:0,0);Check(Mathf.Abs(cart.GetComponent<Renderer>().bounds.min.y-.115f)<1e-5,"flange height same");var target=cart.transform.position+Vector3.up*.6f;foreach(var view in new[]{"normal","close","opposite"}){sun.transform.rotation=Quaternion.Euler(45,view=="opposite"?150:-30,0);c.transform.position=target+(view=="normal"?new Vector3(0,9,-6.3f):view=="close"?new Vector3(2.2f,2.2f,-3):new Vector3(-2.2f,2.2f,3));c.transform.LookAt(target);Shot(c,shape+"-"+view+"-"+id);}UnityEngine.Object.DestroyImmediate(cart);}UnityEngine.Object.DestroyImmediate(rail);}}
 public static void Field(){Empty();var result=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"Loaded183");Check(result.built,"formal product tunnel");var c=Cam();var hero=new GameObject("camera anchor").transform;hero.position=new Vector3(12,0,10.5f);var cut=result.root.GetComponent<MapTunnels.MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=c;for(int i=0;i<2;i++){var rail=Prop("mine_rail_straight");rail.transform.position=new Vector3(12,0,13.5f-i*2);}
 foreach(var id in new[]{"minecart","minecart_loaded"}){var cart=Prop(id);cart.transform.position=new Vector3(12,.14f,10.5f);foreach(var view in new[]{"normal","close","reverse"}){var target=cart.transform.position+Vector3.up*.6f;c.transform.position=view=="normal"?hero.position+new Vector3(0,9,-6.3f):target+(view=="close"?new Vector3(-.9f,1.3f,-1.7f):new Vector3(.9f,1.3f,1.7f));c.transform.LookAt(view=="normal"?hero.position+Vector3.up*.5f:target);typeof(MapTunnels.MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);Shot(c,"mine-"+view+"-"+id);}UnityEngine.Object.DestroyImmediate(cart);}File.WriteAllText(Path.Combine(Out,"field.json"),"{\"formalProductTunnel\":true,\"input\":\"Input123Mine\",\"width\":2.4,\"height\":2.8,\"cart\":[12,0.14,10.5],\"existingLights\":"+result.lights+",\"originalGameSceneChanged\":false}");}
 [Serializable]class LoadRow{public string id;public int placed,visible,meshes,materials,textures;public long meshBytes,textureBytes;public double cpuMedianMs;}
 public static void Load(){var rows=new List<LoadRow>();foreach(var id in new[]{"minecart","minecart_loaded"})foreach(int count in new[]{9,225}){Empty();var c=Cam();c.transform.position=new Vector3(0,24,-20);c.transform.LookAt(Vector3.zero);var root=new GameObject("shared");int side=count==9?3:15;for(int i=0;i<count;i++){var o=Prop(id);o.transform.SetParent(root.transform,false);o.transform.position=new Vector3((i%side-side/2)*2,0,(i/side-side/2)*2);}var rs=root.GetComponentsInChildren<Renderer>();var meshes=root.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).Distinct().ToArray();var mats=rs.Select(x=>x.sharedMaterial).Distinct().ToArray();var tx=mats.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_MetallicGlossMap"),m.GetTexture("_BumpMap")}).Distinct().ToArray();Check(meshes.Length==1&&mats.Length==1&&tx.Length==3,"shared assets");var rt=new RenderTexture(640,360,24);rt.Create();c.targetTexture=rt;var times=new List<double>();for(int i=0;i<10;i++){var sw=System.Diagnostics.Stopwatch.StartNew();c.Render();sw.Stop();if(i>=4)times.Add(sw.Elapsed.TotalMilliseconds);}times.Sort();var planes=GeometryUtility.CalculateFrustumPlanes(c);rows.Add(new LoadRow{id=id,placed=count,visible=rs.Count(r=>GeometryUtility.TestPlanesAABB(planes,r.bounds)),meshes=meshes.Length,materials=mats.Length,textures=tx.Length,meshBytes=meshes.Sum(x=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(x)),textureBytes=tx.Sum(x=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(x)),cpuMedianMs=times[times.Count/2]});c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}File.WriteAllText(Path.Combine(Out,"load.json"),"{\"gpuMeasured\":false,\"cpuSubmissionNotFrameGuarantee\":true,\"rows\":["+string.Join(",",rows.Select(x=>JsonUtility.ToJson(x)))+"]}");}

 [Serializable]class TextureRow{public string name,path;public int width,height;public bool readable;public long bytes;}
 public static void Coexist(){var rows=new List<string>();foreach(int count in new[]{9,225}){Empty();var root=new GameObject("mixed");for(int i=0;i<count;i++){var o=Prop(i%2==0?"minecart":"minecart_loaded");o.transform.SetParent(root.transform,false);o.transform.position=new Vector3((i%15-7)*2,0,(i/15-7)*2);}var mats=root.GetComponentsInChildren<Renderer>().Select(r=>r.sharedMaterial).Distinct().ToArray();var ts=mats.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_MetallicGlossMap"),m.GetTexture("_BumpMap")}).Distinct().Cast<Texture2D>().ToArray();Check(mats.Length==2&&ts.Length==6,"coexist six actual references");var descriptions=ts.Select(t=>JsonUtility.ToJson(new TextureRow{name=t.name,path=AssetDatabase.GetAssetPath(t),width=t.width,height=t.height,readable=t.isReadable,bytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t)}));rows.Add("{\"placed\":"+count+",\"materials\":2,\"textureReferences\":6,\"textureBytes\":"+ts.Sum(t=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t))+",\"textures\":["+string.Join(",",descriptions)+"]}");}File.WriteAllText(Path.Combine(Out,"coexist.json"),"{\"gpuMeasured\":false,\"rows\":["+string.Join(",",rows)+"]}");}
}
